import { useId, type CSSProperties, type ReactNode } from "react";
import { logoClips, logoLayers, logoViewBox, type LogoLayer } from "./logo-data";
import "./kubbe-logo.css";

type Props = {
  /** Draw the logo stroke by stroke, then fade the colour in. */
  animate?: boolean;
  /** Accessible name. Pass an empty string when the logo is decorative. */
  label?: string;
  className?: string;
};

/**
 * The Kubbe mark: a carved wooden hand holding a trout.
 * The drawing data is generated by design/logo/generate.js.
 */
export function KubbeLogo({ animate = false, label = "Kubbe", className }: Props) {
  const id = useId();
  const clipId = (index: number) => `${id}-clip-${index}`;

  // A layer may be confined to several clips at once: nest one group per clip.
  const confine = (layer: LogoLayer, node: ReactNode) =>
    (layer.c ?? []).reduce<ReactNode>(
      (inner, clip) => <g clipPath={`url(#${clipId(clip)})`}>{inner}</g>,
      node,
    );

  return (
    <svg
      viewBox={logoViewBox}
      className={["kubbe-logo", animate ? "kubbe-logo--animate" : "", className ?? ""].filter(Boolean).join(" ")}
      strokeLinecap="round"
      strokeLinejoin="round"
      role={label ? "img" : undefined}
      aria-label={label || undefined}
      aria-hidden={label ? undefined : true}
    >
      <defs>
        {logoClips.map((d, index) => (
          <clipPath key={index} id={clipId(index)}>
            <path d={d} />
          </clipPath>
        ))}
      </defs>
      {logoLayers.map((layer, index) => {
        const timing = { "--t": `${layer.t}s`, "--u": `${layer.u}s` } as CSSProperties;
        switch (layer.k) {
          case "s":
            return (
              <path
                key={index}
                className="kubbe-logo__shape"
                style={{ ...timing, "--f": layer.f } as CSSProperties}
                d={layer.d}
                strokeWidth={layer.w}
                pathLength={1}
              />
            );
          case "l":
            return (
              <g key={index}>
                {confine(
                  layer,
                  <path
                    className="kubbe-logo__line"
                    style={timing}
                    d={layer.d}
                    strokeWidth={layer.w}
                    pathLength={1}
                  />,
                )}
              </g>
            );
          case "t":
            return (
              <g key={index}>
                {confine(
                  layer,
                  <path
                    className="kubbe-logo__tint"
                    style={timing}
                    d={layer.d}
                    fill={layer.f}
                    transform={layer.x}
                  />,
                )}
              </g>
            );
          case "i":
            return <path key={index} className="kubbe-logo__ink" style={timing} d={layer.d} />;
        }
      })}
    </svg>
  );
}
